# Create a proper mock using subclassing
conftest = '''"""Shared fixtures for crucible_hidden tests."""
import sys
from unittest.mock import patch, MagicMock
import datetime as _real_datetime
import pytest


class MockDate(_real_datetime.date):
    """A date subclass that returns a fixed value for today()."""
    def __new__(cls, year, month, day):
        return super().__new__(cls, year, month, day)

    @classmethod
    def today(cls):
        return cls._today_value

    @classmethod  
    def _set_today(cls, d):
        cls._today_value = d


class MockDatetime(_real_datetime.datetime):
    """A datetime subclass that returns a fixed value for now()."""
    def __new__(cls, *args, **kwargs):
        return super().__new__(cls, *args, **kwargs)

    @classmethod
    def now(cls, tz=None):
        if tz is None:
            # Return naive datetime
            return cls._now_naive.replace(tzinfo=None)
        else:
            # Return aware datetime in given timezone
            return cls._now_aware.astimezone(tz)


@pytest.fixture
def monkeypatch_datetime(monkeypatch):
    """Replace datetime module in sys.modules with mocks.

    Usage: monkeypatch_datetime(date_today, datetime_now=None)
    """
    def _impl(date_today, datetime_now=None):
        if datetime_now is None:
            datetime_now = _real_datetime.datetime.now()

        # Set class-level values on our mock classes
        MockDate._set_today(date_today)
        MockDatetime._now_naive = datetime_now.replace(tzinfo=None)
        MockDatetime._now_aware = datetime_now

        # Create a mock module that has our mock classes
        mock_mod = MagicMock(spec=_real_datetime)
        mock_mod.date = MockDate
        mock_mod.datetime = MockDatetime
        mock_mod.timedelta = _real_datetime.timedelta
        mock_mod.timezone = _real_datetime.timezone
        mock_mod.MINYEAR = _real_datetime.MINYEAR
        mock_mod.MAXYEAR = _real_datetime.MAXYEAR

        monkeypatch.setitem(sys.modules, 'datetime', mock_mod)
        return mock_mod
    return _impl
'''

with open('crucible_hidden/conftest.py', 'w') as f:
